import axios from 'axios';

const API_URL = 'http://localhost:8080/api';

const api = axios.create({
  baseURL: API_URL,
  headers: {
    'Content-Type': 'application/json',
  },
});

// Add token to requests if it exists
api.interceptors.request.use((config) => {
  const token = localStorage.getItem('token');
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

// Auth endpoints
export const registerUser = (userData) => api.post('/auth/register', userData);
export const loginUser = (credentials) => api.post('/auth/login', credentials);

// Artwork endpoints
export const getAllArtworks = () => api.get('/artworks');
export const getArtistArtworks = (artistId) => api.get(`/artworks/artist/${artistId}`);
export const createArtwork = (formData) => {
  // For file uploads, we need to set the correct content type
  const config = {
    headers: {
      'Content-Type': 'multipart/form-data',
    },
  };
  return api.post('/artworks', formData, config);
};
export const likeArtwork = (artworkId) => api.post(`/artworks/${artworkId}/like`);
export const commentOnArtwork = (artworkId, comment) => api.post(`/artworks/${artworkId}/comment`, { comment });
export const searchArtworks = (query) => api.get(`/artworks/search?q=${query}`);

// Artist endpoints
export const followArtist = (artistId) => api.post(`/artists/${artistId}/follow`);
export const getArtistMessages = (artistId) => api.get(`/artists/${artistId}/messages`);

export default api;
